// Characterization tests: pin the HTTP behavior clients see today, quirks included.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { apple: 2, pear: 3.5, tv: 150, cheap: 0.3 }
const pricing = { priceOf: async (sku) => prices[sku] }
let server, base

before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST',
  headers: { 'content-type': 'application/json' },
  body: raw ?? JSON.stringify(body),
})

test('POST /orders creates an order: 201, JSON, string id, echoed items, total', async () => {
  const items = [{ sku: 'apple', qty: 3 }]
  const res = await post({ items })
  assert.equal(res.status, 201)
  assert.equal(res.headers.get('content-type'), 'application/json')
  assert.deepEqual(Object.keys(await res.clone().json()).sort(), ['id', 'items', 'total'])
  const order = await res.json()
  assert.equal(typeof order.id, 'string')
  assert.deepEqual(order.items, items)
  assert.equal(order.total, 6)
})

test('ids are sequential strings', async () => {
  const a = await (await post({ items: [{ sku: 'apple', qty: 1 }] })).json()
  const b = await (await post({ items: [{ sku: 'apple', qty: 1 }] })).json()
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('total sums multiple lines', async () => {
  const order = await (await post({ items: [{ sku: 'apple', qty: 2 }, { sku: 'pear', qty: 2 }] })).json()
  assert.equal(order.total, 11)
})

test('total is floored to a whole number', async () => {
  const order = await (await post({ items: [{ sku: 'pear', qty: 1 }] })).json()
  assert.equal(order.total, 3)
})

test('10% discount applies only when total is strictly over 100', async () => {
  const at100 = await (await post({ items: [{ sku: 'apple', qty: 50 }] })).json()
  assert.equal(at100.total, 100)
  const over = await (await post({ items: [{ sku: 'apple', qty: 51 }] })).json()
  assert.equal(over.total, 91) // 102 - 10.2 = 91.8 -> floor
  const tv = await (await post({ items: [{ sku: 'tv', qty: 1 }] })).json()
  assert.equal(tv.total, 135)
})

test('discount is applied before flooring', async () => {
  const order = await (await post({ items: [{ sku: 'cheap', qty: 340 }] })).json() // 102 -> 91.8
  assert.equal(order.total, 91)
})

test('GET /orders/:id returns the created order', async () => {
  const created = await (await post({ items: [{ sku: 'pear', qty: 2 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.equal(res.headers.get('content-type'), 'application/json')
  assert.deepEqual(await res.json(), created)
})

test('GET unknown order returns 200 with { error: "not found" } (not 404)', async () => {
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

for (const [name, body, raw] of [
  ['missing items', {}],
  ['empty items', { items: [] }],
  ['items not an array', { items: 'apple' }],
  ['invalid JSON', null, '{nope'],
  ['null body', null, 'null'],
]) {
  test(`POST /orders rejects ${name}: 400 { error: "items required" }`, async () => {
    const res = await post(body, raw)
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  })
}

test('empty POST body is treated as {} and rejected with 400', async () => {
  const res = await fetch(`${base}/orders`, { method: 'POST' })
  assert.equal(res.status, 400)
  assert.deepEqual(await res.json(), { error: 'items required' })
})

test('rejected orders do not consume ids', async () => {
  const a = await (await post({ items: [{ sku: 'apple', qty: 1 }] })).json()
  await post({ items: [] })
  const b = await (await post({ items: [{ sku: 'apple', qty: 1 }] })).json()
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('unknown routes and methods return 404 { error: "no route" }', async () => {
  for (const [method, path] of [
    ['GET', '/'], ['GET', '/orders'], ['DELETE', '/orders/1'],
    ['PUT', '/orders'], ['GET', '/orders/1/extra'], ['POST', '/orders/1'],
  ]) {
    const res = await fetch(base + path, { method })
    assert.equal(res.status, 404, `${method} ${path}`)
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})

test('query strings are ignored when routing', async () => {
  const created = await (await post({ items: [{ sku: 'apple', qty: 1 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}?x=1`)
  assert.deepEqual(await res.json(), created)
})
